 var style=document.createElement("style");style.textContent=".writing-card{margin:18px 0;padding:18px;border:1px solid #dce6f7;border-radius:17px;background:linear-gradient(145deg,#f7f9ff,#fff)}.writing-card textarea{display:block;width:100%;box-sizing:border-box;min-height:90px;resize:vertical;border:1px solid #cbd7ee;border-radius:12px;padding:13px;font:inherit;line-height:1.6;color:#20345d;background:#fff}.writing-tools{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-top:10px}.writing-feedback{min-height:24px;font-weight:750;color:#276b57}.writing-card .tag{margin:0 0 8px}";document.head.appendChild(style);
 stages.forEach(function(x,i){var input=document.getElementById("writing-input-"+i),count=document.getElementById("writing-count-"+i),fb=document.getElementById("writing-feedback-"+i);input.addEventListener("input",function(){var n=input.value.trim()?input.value.trim().split(/\s+/).length:0;count.textContent=n+" palabras";});document.querySelector('[data-writing-review="'+i+'"]').addEventListener("click",function(){var value=input.value.trim();if(!value){fb.textContent="Escribe primero tu respuesta y vuelve a revisarla.";return;}var n=value.split(/\s+/).length,lower=value.toLowerCase(),used=bank.filter(function(w){return lower.includes(w.toLowerCase());}),tips=[];if(!/^[A-Z]/.test(value))tips.push("Empieza con mayúscula.");if(!/[.!?]$/.test(value))tips.push("Añade un punto al final.");if(n<x.min)tips.push("Amplía tu respuesta: intenta escribir un poco más.");if(used.length<x.needed)tips.push("Incorpora más palabras del banco de vocabulario.");fb.textContent=tips.length?"Para mejorar: "+tips.join(" "):"¡Buen trabajo! Has revisado el vocabulario y la presentación. Lee tu texto en voz alta.";});});
