(function(){var nav=document.querySelector("nav"),main=document.querySelector("main");if(!nav||!main||typeof data==="undefined")return;[["grammar","3. Grammar","Gramática"],["reading","4. Reading","Reading · Comprensión lectora"],["listening","5. Listening","Listening · Comprensión auditiva"]].forEach(function(d){var b=document.createElement("button");b.type="button";b.dataset.tab=d[0];b.textContent=d[1];nav.appendChild(b);var p=document.createElement("section");p.id=d[0];p.className="panel";p.innerHTML="<h2>"+d[2]+"</h2><div id='"+d[0]+"-content'></div>";main.appendChild(p);});var words=data.words.map(function(w){return String(w[0]);}),sentences=data.qs.filter(function(q){return q.type!=="Traduce la palabra"&&q.en&&/[.!?]/.test(q.en);}),unique=[];sentences.forEach(function(q){if(!unique.includes(q.en)&&unique.length<10)unique.push(q.en);});var rules=[[/^I can see the /i,"I can see the…","Usamos «I can see the + nombre» para decir «Puedo ver el/la…»."],[/^Where is the /i,"Where is the…?","Usamos «Where is the…?» para preguntar dónde está algo."],[/^I like the /i,"I like the…","Usamos «I like the + nombre» para expresar gustos."],[/^This is the /i,"This is the…","Usamos «This is the…» para identificar algo."],[/^I have /i,"I have…","Usamos «I have…» para decir lo que tenemos."],[/^It is /i,"It is…","Usamos «It is…» para describir algo."]].filter(function(p){return sentences.some(function(q){return p[0].test(q.en);});});document.getElementById("grammar-content").innerHTML=rules.map(function(p){var q=sentences.find(function(x){return p[0].test(x.en);});return "<article class='skill-card'><b>"+p[1]+"</b><p>"+p[2]+"</p><p class='skill-example'>"+(q?q.en:"")+"</p></article>";}).join("")+"<article class='skill-card'><h3>Practica la estructura</h3><p id='gq' class='question'></p><div id='go' class='answers'></div><p id='gf' class='feedback'></p><button id='gn' hidden>Siguiente</button></article>";var gi=0,gs=sentences.slice(0,8);function gr(){var q=gs[gi];if(!q){document.getElementById("gq").textContent="¡Has terminado!";document.getElementById("go").innerHTML="";return;}document.getElementById("gq").textContent=q.en;document.getElementById("gf").textContent="Elige la traducción correcta.";document.getElementById("gn").hidden=true;document.getElementById("go").innerHTML=q.opts.map(function(x){return "<button type='button'>"+x+"</button>";}).join("");document.querySelectorAll("#go button").forEach(function(b){b.onclick=function(){document.querySelectorAll("#go button").forEach(function(x){x.disabled=true;});document.getElementById("gf").textContent=b.textContent===q.es?"✓ Correcto.":"La respuesta correcta es: "+q.es;document.getElementById("gn").hidden=false;};});}document.getElementById("gn").onclick=function(){gi++;gr();};gr();var passage=unique.slice(0,6);if(!passage.length)passage=words.slice(0,6).map(function(w){return "This is the "+w+".";});document.getElementById("reading-content").innerHTML="<p class='muted'>Lee estas frases en inglés y después comprueba tu comprensión.</p><div class='skill-passage'>"+passage.join(" ")+"</div><article class='skill-card'><h3>Comprensión lectora</h3><p id='rq' class='question'></p><div id='ro' class='answers'></div><p id='rf' class='feedback'></p><button id='rn' hidden>Siguiente</button></article>";var ri=0;function rd(){var target=words[ri%words.length],opts=[target].concat(words.filter(function(w){return w!==target;}).slice(ri%Math.max(1,words.length-1),ri%Math.max(1,words.length-1)+2));document.getElementById("rq").textContent="Which word from the mission vocabulary can you identify in the text?";document.getElementById("rf").textContent="Selecciona una palabra del vocabulario.";document.getElementById("rn").hidden=true;document.getElementById("ro").innerHTML=opts.map(function(x){return "<button type='button'>"+x+"</button>";}).join("");document.querySelectorAll("#ro button").forEach(function(b){b.onclick=function(){document.querySelectorAll("#ro button").forEach(function(x){x.disabled=true;});document.getElementById("rf").textContent=b.textContent===target?"✓ ¡Muy bien!":"Vuelve a leer y busca: "+target;document.getElementById("rn").hidden=false;};});}document.getElementById("rn").onclick=function(){ri++;if(ri>=Math.min(6,words.length)){document.getElementById("rq").textContent="¡Has completado la lectura!";document.getElementById("ro").innerHTML="";document.getElementById("rn").hidden=true;}else rd();};rd();var ls=sentences.slice(-8);if(!ls.length)ls=words.map(function(w){return {en:w};});document.getElementById("listening-content").innerHTML="<p class='muted'>Escucha las frases en inglés británico. Puedes repetir el audio y mostrar la transcripción.</p><article class='skill-card'><button type='button' class='primary' id='lp'>🔊 Escuchar audio</button> <button type='button' id='showt'>Mostrar transcripción</button><p id='lt' class='skill-passage' hidden></p><p id='lq' class='question'>¿Qué palabra escuchas?</p><div id='lo' class='answers'></div><p id='lf' class='feedback'></p><button id='ln' hidden>Siguiente audio</button></article>";var li=0;function lr(){var q=ls[li],target=words.find(function(w){return q.en.toLowerCase().includes(w.toLowerCase());})||words[li%words.length],opts=[target].concat(words.filter(function(w){return w!==target;}).slice(li%Math.max(1,words.length-1),li%Math.max(1,words.length-1)+2));document.getElementById("lt").textContent=q.en;document.getElementById("lt").hidden=true;document.getElementById("lf").textContent="Pulsa «Escuchar audio» y selecciona la palabra que oigas.";document.getElementById("ln").hidden=true;document.getElementById("lo").innerHTML=opts.map(function(x){return "<button type='button'>"+x+"</button>";}).join("");document.getElementById("lp").onclick=function(){if(!window.speechSynthesis)return;speechSynthesis.cancel();var u=new SpeechSynthesisUtterance(q.en);u.lang="en-GB";speechSynthesis.speak(u);};document.querySelectorAll("#lo button").forEach(function(b){b.onclick=function(){document.querySelectorAll("#lo